// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.reflect.Method;

import org.junit.jupiter.api.Test;

class FrontierOmniIndexTest {

	@Test
	void samplingQualityCombinesReplicaDispersionWitnessSupportAndRepresentedMass() throws Exception {
		Class<?> qualityType = Class.forName("org.eclipse.rdf4j.sail.lmdb.frontier.FrontierSamplingQuality");
		Method fromLanes = qualityType.getDeclaredMethod(
				"fromLanes", double[].class, int.class, long.class, double.class, int.class, boolean.class);
		fromLanes.setAccessible(true);
		Object stable = fromLanes.invoke(null,
				new double[] { 100.0d, 101.0d, 99.0d, 100.0d }, 4, 256L, 1.0d, 1, false);
		Object weak = fromLanes.invoke(null,
				new double[] { 20.0d, 80.0d, 320.0d, 1_280.0d }, 4, 3L, 0.01d, 3, false);

		double stableRse = metric(qualityType, stable, "relativeStandardError");
		double stableEffectiveSize = metric(qualityType, stable, "effectiveSampleSize");
		double stableConfidence = metric(qualityType, stable, "confidence");
		double weakRse = metric(qualityType, weak, "relativeStandardError");
		double weakEffectiveSize = metric(qualityType, weak, "effectiveSampleSize");
		double weakConfidence = metric(qualityType, weak, "confidence");
		long weakWitnesses = ((Number) qualityType.getDeclaredMethod("sharedWitnesses").invoke(weak)).longValue();
		Method isWeak = qualityType.getDeclaredMethod("isWeak", long.class, double.class, double.class);

		assertTrue(stableRse < 0.01d, stable::toString);
		assertTrue(stableEffectiveSize > 250.0d, stable::toString);
		assertTrue(stableConfidence > 0.95d, stable::toString);
		assertFalse((boolean) isWeak.invoke(stable, 8L, 0.75d, 0.05d));

		assertTrue(weakRse > 0.75d, weak::toString);
		assertTrue(weakEffectiveSize < weakWitnesses, weak::toString);
		assertTrue(weakConfidence < stableConfidence, weak::toString);
		assertTrue((boolean) isWeak.invoke(weak, 8L, 0.75d, 0.05d));
	}

	private static double metric(Class<?> qualityType, Object quality, String name) throws Exception {
		return ((Number) qualityType.getDeclaredMethod(name).invoke(quality)).doubleValue();
	}

	@Test
	void projectedDistinctUsesDesignMeanAcrossSparseLanes() throws Exception {
		Method aggregate = FrontierOmniIndex.class.getDeclaredMethod(
				"projectedDistinctLaneMean", double[].class, int.class);
		aggregate.setAccessible(true);

		assertEquals(26_702.0d,
				(double) aggregate.invoke(null, new double[] { 0.0d, 0.0d, 106_808.0d, 0.0d }, 4), 0.0d);
		assertTrue(Double.isNaN(
				(double) aggregate.invoke(null, new double[] { 0.0d, Double.NaN, 106_808.0d, 0.0d }, 4)),
				"an unavailable lane must make the complete design ensemble unavailable");
	}

	@Test
	void projectedDistinctMeanDoesNotDependOnObservedZeros() throws Exception {
		Method aggregate = FrontierOmniIndex.class.getDeclaredMethod(
				"projectedDistinctLaneMean", double[].class, int.class);
		aggregate.setAccessible(true);

		assertEquals(25.75d,
				(double) aggregate.invoke(null, new double[] { 1.0d, 1.0d, 1.0d, 100.0d }, 4), 0.0d,
				"rare support must not be discarded merely because every lane is positive");
		assertEquals(100.0d,
				(double) aggregate.invoke(null, new double[] { 90.0d, 100.0d, 100.0d, 110.0d }, 4), 0.0d);
	}

	@Test
	void projectedDistinctFinalizationDistinguishesEmptyFromUnobserved() throws Exception {
		Method finalizeEstimate = FrontierOmniIndex.class.getDeclaredMethod(
				"finalizeProjectedDistinct", double.class, FrontierLeafEstimate.class);
		finalizeEstimate.setAccessible(true);
		FrontierLeafEstimate possibleRows = new FrontierLeafEstimate(
				10.0d, 0.0d, 24_971.0d, 0.5d, "test", FrontierFallbackReason.NONE);
		FrontierLeafEstimate emptyRows = new FrontierLeafEstimate(
				0.0d, 0.0d, 0.0d, 1.0d, "test", FrontierFallbackReason.NONE);

		assertTrue(Double.isNaN((double) finalizeEstimate.invoke(null, 0.0d, possibleRows)),
				"zero witnesses cannot prove that a possibly nonempty projection is empty");
		assertEquals(0.0d, (double) finalizeEstimate.invoke(null, 0.0d, emptyRows), 0.0d);
		assertEquals(24_971.0d, (double) finalizeEstimate.invoke(null, 26_702.0d, possibleRows), 0.0d,
				"only the completed design mean is capped by the leaf upper bound");
	}

	@Test
	void joinQualityWidensDispersedLaneEnsemblesInsteadOfCountingAvailableReplicas() throws Exception {
		Method aggregate = FrontierOmniIndex.class.getDeclaredMethod("sampledJoinEstimate",
				double[].class, int.class, long.class, double.class, int.class, String.class);
		aggregate.setAccessible(true);
		FrontierJoinEstimate stable = (FrontierJoinEstimate) aggregate.invoke(null,
				new double[] { 99.0d, 100.0d, 100.0d, 101.0d }, 4, 256L, 1_000.0d, 3,
				"frontier-v2-omni-path");
		FrontierJoinEstimate weak = (FrontierJoinEstimate) aggregate.invoke(null,
				new double[] { 20.0d, 80.0d, 320.0d, 1_280.0d }, 4, 3L, 2_000.0d, 3,
				"frontier-v2-omni-path");

		assertTrue(stable.confidence() > weak.confidence(), () -> stable + " versus " + weak);
		assertTrue(stable.lowerRows() > 0.0d && stable.upperRows() < 1_000.0d, stable::toString);
		assertEquals(0.0d, weak.lowerRows(), weak::toString);
		assertEquals(2_000.0d, weak.upperRows(), weak::toString);
	}

	@Test
	void bottomKDistinctUsesWithoutReplacementInclusionProbability() throws Exception {
		Method method = FrontierOmniIndex.class.getDeclaredMethod(
				"bottomKInclusionProbability", long.class, int.class, double.class);
		method.setAccessible(true);

		double twoOccurrences = (double) method.invoke(null, 100L, 10, 2.0d);
		assertEquals(1.0d - 90.0d * 89.0d / (100.0d * 99.0d), twoOccurrences, 1.0e-12d);
		assertTrue(Math.abs(twoOccurrences - (1.0d - 0.9d * 0.9d)) > 1.0e-4d,
				"bottom-K sampling must not silently use the Bernoulli formula");

		double twentyBillion = (double) method.invoke(null, 20_000_000_000L, 8_192, 1.0d);
		assertEquals(8_192.0d / 20_000_000_000.0d, twentyBillion, 1.0e-15d);
	}
}
